package main

import (
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/gitdek/invariant/internal/gobra"
	"github.com/gitdek/invariant/internal/project"
	"github.com/gitdek/invariant/internal/tla"
	"github.com/gitdek/invariant/internal/toolchain"
)

// Reuse the existing TLC command-boundary fake, including its validation of
// staging, flags, bounds and included model bytes. Only Gobra is stalled.
func TestGobra946CIGateLogNamesTheUnfinishedProof(t *testing.T) {
	tc, _ := reader603Tools(t)
	tc.GobraImage, tc.GoImage = "gobra946-timeout", "gobra946-go"
	bin := t.TempDir()
	exe, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	script := `#!/bin/sh
case " $* " in
  *" gobra946-timeout "*)
    printf '%s\n' 'Gobra is still solving the submitted package'
    exec sleep 60 ;;
  *" gobra946-go "*)
    printf '%s\n' '@@invariant vet=0' '@@invariant test=0' 'invariant-agreement states=3 depth=3' '@@invariant agree=0'
    exit 0 ;;
esac
export INVARIANT_READER603_DOCKER=1
exec '` + strings.ReplaceAll(exe, "'", "'\"'\"'") + `' "$@"
`
	if err := os.WriteFile(filepath.Join(bin, "docker"), []byte(script), 0o755); err != nil {
		t.Fatal(err)
	}
	t.Setenv("PATH", bin+string(os.PathListSeparator)+os.Getenv("PATH"))
	t.Setenv("INVARIANT_CONTAINER_CPUS", "1")
	oldToolchain, oldTimeout := verifyToolchain, gobra.Timeout
	verifyToolchain = func(context.Context) (toolchain.Toolchain, error) { return tc, nil }
	gobra.Timeout = time.Second
	t.Cleanup(func() { verifyToolchain, gobra.Timeout = oldToolchain, oldTimeout })

	dir := t.TempDir()
	m := project.Manifest{Name: "Gobra timeout", Module: ".invariant/specs/Reader603.tla", Code: "machine", Language: "go"}
	lock := project.Lock{Decision: "timeout-fixture", Bounds: map[string]string{"Limit": "2"}, Statements: []project.Statement{
		{Name: "Spec", Kind: project.Spec, Says: "Advance, reset or poll."},
		{Name: "Safe", Kind: project.Invariant, Says: "The count stays within its limit."},
	}}
	for i := range lock.Statements {
		h, err := tla.PinHashWith(reader603Model, map[string]string{"Helper603.tla": reader603Include}, lock.Statements[i].Name, project.Model)
		if err != nil {
			t.Fatal(err)
		}
		lock.Statements[i].SHA256 = h
	}
	for name, body := range map[string]string{
		".invariant/invariant.json":      string(reader603JSON(t, m)),
		".invariant/ratified.lock":       string(reader603JSON(t, lock)),
		".invariant/specs/Reader603.tla": reader603Model,
		".invariant/specs/Helper603.tla": reader603Include,
		"go.mod":                         "module example/timeout\n\ngo 1.27.1\n",
		"machine/ops.go":                 "// +gobra\npackage machine\nfunc EndlessProof() {}\n",
		"machine/explore.go":             "package machine\ntype State int\nfunc Init() State { return 0 }\nfunc Successors(s State) []State { return []State{(s+1)%3} }\n",
	} {
		reader603Write(t, filepath.Join(dir, name), body)
	}
	log, err := os.CreateTemp(t.TempDir(), "stderr-")
	if err != nil {
		t.Fatal(err)
	}
	defer log.Close()
	oldStderr := os.Stderr
	os.Stderr = log
	t.Cleanup(func() { os.Stderr = oldStderr })
	ctx, cancel := context.WithTimeout(context.Background(), 15*time.Second)
	defer cancel()
	out := filepath.Join(t.TempDir(), "receipt")
	status := verifyCmd(ctx, []string{"-out", out, dir})
	os.Stderr = oldStderr
	if status != 2 {
		t.Fatalf("timeout exit = %d, want gate-error exit 2", status)
	}
	b, err := os.ReadFile(log.Name())
	if err != nil {
		t.Fatal(err)
	}
	text := string(b)
	for _, want := range []string{"didn't finish within 1s", "EndlessProof", "ops.go"} {
		if !strings.Contains(text, want) {
			t.Errorf("CI gate log lost %q: %s", want, text)
		}
	}
	if strings.Contains(text, dir) || strings.Contains(text, "ExplorerOnly") {
		t.Errorf("timeout log includes private or unverified names: %s", text)
	}
	if _, err := os.Stat(filepath.Join(out, "receipt.json")); !os.IsNotExist(err) {
		t.Fatalf("timeout wrote a completed receipt, or stat failed: %v", err)
	}
}

