package factory

import (
	"fmt"
	"strings"
	"testing"
	"time"

	"github.com/gitdek/invariant/internal/gobra"
	"github.com/gitdek/invariant/internal/verify"
)

// The structured timeout is also returned by gobra.Run. Its Error method is
// the compatibility boundary for all existing callers, including the gate
// tool and synth's final gate; neither caller needs to flatten progress into
// an invented failed Code check. Duration is a time.Duration and uses the
// duration_ns JSON field of completed progress records.
func TestGobra946FactoryPostKeepsPartialProofProgress(t *testing.T) {
	progress := gobra.Progress{
		Unfinished: []gobra.Member{
			{Source: "ops.go", Symbol: "(*Worker).Start"},
			{Source: "other.go", Symbol: "Other.Start"},
		},
		Active: []gobra.Member{{Source: "ops.go", Symbol: "(*Worker).Start"}},
	}
	for i := 0; i < 8; i++ {
		progress.Completed = append(progress.Completed, gobra.Timing{
			Source: "done.go", Symbol: fmt.Sprintf("Finished%d", i), Duration: time.Duration(i+1) * time.Second,
		})
	}
	deadline := &gobra.TimeoutError{Limit: 20 * time.Minute, Progress: progress}
	// Match the existing public-error conversion and synthesis wrapping on
	// the actual final-gate path, then use the real factory comment renderer.
	err := fmt.Errorf("the final gate couldn't run: %w", verify.Public(deadline))
	text := buildFailedComment(nil, nil, err, Marker{})
	for _, want := range []string{"I couldn't build the code", "the final gate couldn't run", "20m0s", "ops.go", "(*Worker).Start", "other.go", "Other.Start"} {
		if !strings.Contains(text, want) {
			t.Errorf("factory timeout post lost %q: %s", want, text)
		}
	}
	for i := 0; i < 8; i++ {
		symbol, duration := fmt.Sprintf("Finished%d", i), (time.Duration(i+1) * time.Second).String()
		found := false
		for _, line := range strings.Split(text, "\n") {
			if strings.Contains(line, "done.go") && strings.Contains(line, symbol) && strings.Contains(line, duration) {
				found = true
			}
		}
		if !found {
			t.Errorf("factory timeout post lost completed proof %s and its time %s: %s", symbol, duration, text)
		}
	}
	if !strings.Contains(strings.ToLower(text), "active") && !strings.Contains(strings.ToLower(text), "in progress") && !strings.Contains(strings.ToLower(text), "verifying") {
		t.Errorf("post did not distinguish the observed active proof: %s", text)
	}
	if strings.Contains(text, "draft pull request") {
		t.Errorf("a verifier timeout unexpectedly claimed a completed draft: %s", text)
	}
}

package gobra_test

import (
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/gitdek/invariant/internal/gobra"
)

// This double deliberately emits no member protocol. The diagnostic must say
// completion was not reported, not pretend it observed a member starting.
// Real protocol capture and timing are also required by the plan's integration
// test, which runs in the existing real-verifier CI lane.
func progress946HangingDocker(t *testing.T) string {
	t.Helper()
	bin := t.TempDir()
	log := filepath.Join(bin, "commands")
	script := `#!/bin/sh
printf '%s\n' "$*" >> "$GOBRA946_COMMANDS"
case "$1" in
  rm) exit 0 ;;
  run)
    printf '%s\n' 'Gobra is still solving the submitted package'
    exec sleep 60 ;;
  *) exit 91 ;;
esac
`
	if err := os.WriteFile(filepath.Join(bin, "docker"), []byte(script), 0o755); err != nil {
		t.Fatal(err)
	}
	t.Setenv("PATH", bin+string(os.PathListSeparator)+os.Getenv("PATH"))
	t.Setenv("GOBRA946_COMMANDS", log)
	t.Setenv("INVARIANT_CONTAINER_CPUS", "1")
	if gobra.Timeout != 20*time.Minute {
		t.Fatalf("default Gobra deadline = %s, want D-0144's 20m", gobra.Timeout)
	}
	old := gobra.Timeout
	gobra.Timeout = time.Second
	t.Cleanup(func() { gobra.Timeout = old })
	return log
}

func progress946Sources(t *testing.T, sources map[string]string) string {
	t.Helper()
	dir := t.TempDir()
	for name, src := range sources {
		if err := os.WriteFile(filepath.Join(dir, name), []byte(src), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	return dir
}

func TestGobra946ShortTimeoutNamesTheFunction(t *testing.T) {
	log := progress946HangingDocker(t)
	dir := progress946Sources(t, map[string]string{
		"stuck.go": "// +gobra\npackage stuck\nfunc EndlessProof() {}\n",
	})
	ctx, cancel := context.WithTimeout(context.Background(), 15*time.Second)
	defer cancel()
	started := time.Now()
	r, err := gobra.Run(ctx, "gobra946-test", dir, true)
	if err == nil || r.Passed {
		t.Fatalf("unfinished verification must remain an error, got %+v, %v", r, err)
	}
	if time.Since(started) > 12*time.Second {
		t.Fatal("short deadline did not stop the verifier promptly")
	}
	for _, want := range []string{"didn't finish within 1s", "stuck.go", "EndlessProof", "Gobra is still solving the submitted package"} {
		if !strings.Contains(err.Error(), want) {
			t.Errorf("timeout lost %q: %v", want, err)
		}
	}
	if strings.Contains(err.Error(), dir) {
		t.Errorf("timeout exposed a temporary host path: %v", err)
	}
	b, readErr := os.ReadFile(log)
	if readErr != nil {
		t.Fatal(readErr)
	}
	commands := string(b)
	for _, want := range []string{"--network none", "--overflow", "/work/stuck.go", "rm --force"} {
		if !strings.Contains(commands, want) {
			t.Errorf("Gobra invocation or cleanup lost %q: %s", want, commands)
		}
	}
}

func TestGobra946TimeoutDistinguishesMethodsAndSelectedSources(t *testing.T) {
	progress946HangingDocker(t)
	dir := progress946Sources(t, map[string]string{
		"a.go":       "// +gobra\npackage proof\ntype Alpha struct{}\nfunc (*Alpha) Start() {}\nfunc Prepare() {}\n",
		"b.go":       "// +gobra\npackage proof\ntype Beta struct{}\nfunc (Beta) Start() {}\n",
		"explore.go": "package proof\nfunc ExplorerOnly() {}\n",
		"a_test.go":  "package proof\nfunc TestOnlyHelper() {}\n",
	})
	_, err := gobra.Run(context.Background(), "gobra946-test", dir, false)
	if err == nil {
		t.Fatal("unfinished verification needs a timeout error")
	}
	text := err.Error()
	for _, want := range []string{"a.go", "(*Alpha).Start", "Prepare", "b.go", "Beta.Start"} {
		if !strings.Contains(text, want) {
			t.Errorf("timeout did not identify %q: %s", want, text)
		}
	}
	for _, absent := range []string{"ExplorerOnly", "TestOnlyHelper", dir} {
		if strings.Contains(text, absent) {
			t.Errorf("timeout included %q: %s", absent, text)
		}
	}
	// Honest absence of reports is a useful fallback, distinct from observed
	// active work. No source-only function can have a measured proof duration.
	lower := strings.ToLower(text)
	if !strings.Contains(lower, "not reported") && !strings.Contains(lower, "unavailable") && !strings.Contains(lower, "unknown") {
		t.Errorf("timeout did not disclose missing member progress: %s", text)
	}
	if strings.Contains(text, "0s") || strings.Contains(text, "0ms") {
		t.Errorf("timeout invented a zero-duration completed proof: %s", text)
	}
}

