package verify_test

import (
	"encoding/json"
	"reflect"
	"strings"
	"testing"

	"github.com/gitdek/invariant/internal/receipt"
	"github.com/gitdek/invariant/internal/verify"
)

// The additive wire contract is code.proof_progress, with completed records
// {source, symbol, duration_ns}, and unfinished and active records
// {source, symbol}. Source is relative to the verified package; symbol uses
// Go receiver notation. Completed means the member's verification finished,
// not that its proof passed. All three lists are operational diagnostics.
func progress946Report(t *testing.T, passed bool) verify.Report {
	t.Helper()
	raw := `{
  "project":"proof timings", "passed":true,
  "design":{"passed":true,"outcome":"passed","distinct_states":3},
  "build":{"passed":true},
  "code":{"verifier":"Gobra","passed":true,
    "functions":["Start","RefuseStart","Quick"],
    "contracts":["Start","RefuseStart","Quick"],
    "overflow_checked":true,
    "proof_progress":{"completed":[
      {"source":"quick.go","symbol":"Quick","duration_ns":250000000},
      {"source":"ops.go","symbol":"(*Worker).RefuseStart","duration_ns":1500000000},
      {"source":"ops.go","symbol":"(*Worker).Start","duration_ns":2500000000}
    ]}
  }
}`
	var r verify.Report
	if err := json.Unmarshal([]byte(raw), &r); err != nil {
		t.Fatal(err)
	}
	r.Passed, r.Code.Passed = passed, passed
	if !passed {
		r.Code.Errors = []string{"ops.go:19: Postcondition might not hold."}
	}
	return r
}

func TestGobra946FinishedTimesReachFeedbackAndReceipt(t *testing.T) {
	for _, passed := range []bool{true, false} {
		r := progress946Report(t, passed)
		before, err := json.Marshal(r)
		if err != nil {
			t.Fatal(err)
		}
		var stored map[string]any
		if err := json.Unmarshal(before, &stored); err != nil {
			t.Fatal(err)
		}
		code := stored["code"].(map[string]any)
		progress, ok := code["proof_progress"].(map[string]any)
		if !ok {
			t.Fatal("report JSON discarded the completed Gobra member timings")
		}
		completed, ok := progress["completed"].([]any)
		if !ok || len(completed) != 3 {
			t.Fatalf("report lost completed timings: %v", progress)
		}
		for label, text := range map[string]string{"gate feedback": verify.Feedback(&r), "CI receipt": receipt.Markdown(&r)} {
			previous := -1
			for _, item := range []struct{ source, symbol, duration string }{
				{"ops.go", "(*Worker).Start", "2.5s"},
				{"ops.go", "(*Worker).RefuseStart", "1.5s"},
				{"quick.go", "Quick", "250ms"},
			} {
				at := strings.Index(text, item.symbol)
				if at < 0 || at <= previous {
					t.Errorf("%s does not name slowest proofs first: %s", label, text)
				}
				previous = at
				found := false
				for _, line := range strings.Split(text, "\n") {
					if strings.Contains(line, item.symbol) && strings.Contains(line, item.source) && strings.Contains(line, item.duration) {
						found = true
					}
				}
				if !found {
					t.Errorf("%s lacks source, symbol and time together for %s: %s", label, item.symbol, text)
				}
			}
			if !passed && !strings.Contains(text, "Postcondition might not hold") {
				t.Errorf("%s lost the verifier's proof failure: %s", label, text)
			}
		}
		if r.Passed != passed || r.Code.Passed != passed {
			t.Fatal("rendering timings changed the proof or gate verdict")
		}
		// The same proof evidence must retain its old fingerprint even if the
		// timing section is absent, reordered or different on another machine.
		fingerprint := verify.Fingerprint(r)
		delete(code, "proof_progress")
		plainJSON, err := json.Marshal(stored)
		if err != nil {
			t.Fatal(err)
		}
		var plain verify.Report
		if err := json.Unmarshal(plainJSON, &plain); err != nil {
			t.Fatal(err)
		}
		if got := verify.Fingerprint(plain); got != fingerprint {
			t.Errorf("operational timings changed the evidence fingerprint: %s != %s", fingerprint, got)
		}
		after, err := json.Marshal(r)
		if err != nil {
			t.Fatal(err)
		}
		if !reflect.DeepEqual(before, after) {
			t.Fatal("rendering or fingerprinting mutated the caller's progress")
		}
		var roundtrip verify.Report
		if err := json.Unmarshal(after, &roundtrip); err != nil {
			t.Fatal(err)
		}
		if verify.Fingerprint(roundtrip) != fingerprint || !strings.Contains(receipt.Markdown(&roundtrip), "2.5s") {
			t.Fatal("JSON round trip lost timing diagnostics or changed the fingerprint")
		}
		if strings.Contains(receipt.Markdown(&plain), "2.5s") {
			t.Fatal("a legacy report invented member timing information")
		}
	}
}
